define('local_studentprofile/rule_builder', ['jquery'], function($) {

    var config = null;
    var $container = null;
    var $hiddenInput = null;

    var operators = {
        'equal': '=',
        'not_equal': '!=',
        'in': 'IN',
        'not_in': 'NOT IN',
        'less': '<',
        'less_or_equal': '<=',
        'greater': '>',
        'greater_or_equal': '>=',
        'between': 'BETWEEN',
        'contains': 'CONTAINS',
        'starts_with': 'STARTS WITH',
        'ends_with': 'ENDS WITH',
    };

    function getFieldConfig(fieldId) {
        return config.fields.find(function(f) { return f.id === fieldId; });
    }

    function createSelect(options, selected, className) {
        var $select = $('<select class="custom-select form-control ' + className + '"></select>');
        $.each(options, function(key, val) {
            var $opt = $('<option value="' + key + '">' + val + '</option>');
            if (key == selected || (Array.isArray(selected) && selected.indexOf(String(key)) !== -1)) {
                $opt.prop('selected', true);
            }
            $select.append($opt);
        });
        return $select;
    }

    function createValueInput(field, rule) {
        var val = rule ? rule.value : '';
        if (field.input === 'select') {
            var $select = createSelect(field.values, val, 'rule-value');
            if (field.multiple) {
                $select.prop('multiple', true);
                $select.css('height', '100px'); // Basic multiselect size
            }
            return $select;
        } else if (field.input === 'number') {
            return $('<input type="number" class="form-control rule-value" value="' + val + '">');
        } else {
            return $('<input type="text" class="form-control rule-value" value="' + val + '">');
        }
    }

    function renderRule(rule) {
        var $ruleRow = $('<div class="rule-row d-flex align-items-center mb-2 p-2 border bg-white shadow-sm"></div>');
        
        // Field Select
        var fieldOpts = {};
        config.fields.forEach(function(f) { fieldOpts[f.id] = f.label; });
        var $fieldSelect = createSelect(fieldOpts, rule ? rule.field : config.fields[0].id, 'rule-field mr-2');
        
        // Operator Select
        var $operatorSelect = $('<select class="custom-select form-control rule-operator mr-2"></select>');
        
        // Value Input Container
        var $valueContainer = $('<div class="rule-value-container flex-grow-1 mr-2"></div>');

        // Delete button
        var $deleteBtn = $('<button type="button" class="btn btn-sm btn-outline-danger btn-delete-rule"><i class="fa fa-trash"></i></button>');

        $ruleRow.append($fieldSelect, $operatorSelect, $valueContainer, $deleteBtn);

        // Update handlers
        $fieldSelect.on('change', function() {
            var field = getFieldConfig($(this).val());
            
            // Update operators
            $operatorSelect.empty();
            field.operators.forEach(function(op) {
                $operatorSelect.append($('<option value="' + op + '">' + (operators[op] || op) + '</option>'));
            });
            
            if (rule && rule.field === field.id && rule.operator) {
                $operatorSelect.val(rule.operator);
            } else {
                $operatorSelect.val(field.operators[0]);
            }

            // Update value input
            $valueContainer.empty();
            $valueContainer.append(createValueInput(field, rule && rule.field === field.id ? rule : null));
            
            serializeBuilder();
        });
        
        $operatorSelect.on('change', serializeBuilder);
        $valueContainer.on('change input', '.rule-value', serializeBuilder);

        $deleteBtn.on('click', function() {
            $ruleRow.remove();
            serializeBuilder();
        });

        // Trigger initial field change to populate operators and value input
        $fieldSelect.trigger('change');

        return $ruleRow;
    }

    function renderGroup(group) {
        var $groupDiv = $('<div class="rule-group p-3 border mb-3 bg-light rounded position-relative"></div>');
        $groupDiv.css('margin-left', '20px');

        // Logic toggle (AND/OR)
        var condition = group ? group.condition : 'AND';
        var $conditionSelect = createSelect({'AND': 'AND', 'OR': 'OR'}, condition, 'group-condition w-auto d-inline-block mr-3 mb-3');
        $conditionSelect.on('change', serializeBuilder);
        
        var $rulesContainer = $('<div class="rules-container"></div>');
        
        var $btnGroup = $('<div class="mt-2"></div>');
        var $addRuleBtn = $('<button type="button" class="btn btn-sm btn-primary mr-2"><i class="fa fa-plus"></i> Add Rule</button>');
        var $addGroupBtn = $('<button type="button" class="btn btn-sm btn-secondary mr-2"><i class="fa fa-plus-circle"></i> Add Group</button>');
        var $deleteGroupBtn = $('<button type="button" class="btn btn-sm btn-outline-danger pull-right"><i class="fa fa-trash"></i> Delete Group</button>');
        
        $btnGroup.append($addRuleBtn, $addGroupBtn, $deleteGroupBtn);
        $groupDiv.append($conditionSelect, $rulesContainer, $btnGroup);

        // Render existing rules
        if (group && group.rules) {
            group.rules.forEach(function(r) {
                if (r.condition) {
                    $rulesContainer.append(renderGroup(r));
                } else {
                    $rulesContainer.append(renderRule(r));
                }
            });
        }

        $addRuleBtn.on('click', function() {
            $rulesContainer.append(renderRule(null));
            serializeBuilder();
        });

        $addGroupBtn.on('click', function() {
            $rulesContainer.append(renderGroup({condition: 'AND', rules: []}));
            serializeBuilder();
        });

        $deleteGroupBtn.on('click', function() {
            $groupDiv.remove();
            serializeBuilder();
        });

        return $groupDiv;
    }

    function serializeGroup($group) {
        var condition = $group.children('.group-condition').val();
        var rules = [];

        $group.children('.rules-container').children().each(function() {
            var $child = $(this);
            if ($child.hasClass('rule-group')) {
                rules.push(serializeGroup($child));
            } else if ($child.hasClass('rule-row')) {
                var fieldId = $child.find('.rule-field').val();
                var operator = $child.find('.rule-operator').val();
                var $valInput = $child.find('.rule-value');
                var val = $valInput.val();
                
                // If it's a number field, cast to float
                var field = getFieldConfig(fieldId);
                if (field.type === 'integer' || field.type === 'double') {
                    val = parseFloat(val);
                }

                rules.push({
                    id: fieldId,
                    field: fieldId,
                    type: field.type,
                    input: field.input || 'text',
                    operator: operator,
                    value: val
                });
            }
        });

        return {
            condition: condition,
            rules: rules,
            valid: true
        };
    }

    function serializeBuilder() {
        var $rootGroup = $container.children('.rule-group').first();
        if ($rootGroup.length) {
            var data = serializeGroup($rootGroup);
            $hiddenInput.val(JSON.stringify(data));
        } else {
            $hiddenInput.val('{"condition":"AND","rules":[],"valid":true}');
        }
    }

    return {
        init: function(builderConfig) {
            config = builderConfig;
            $container = $('#rule-builder-container');
            $hiddenInput = $('input[name="conditions"]');

            $container.empty();

            var initialData = { condition: 'AND', rules: [] };
            if (config.existing_conditions) {
                try {
                    initialData = JSON.parse(config.existing_conditions);
                } catch(e) {
                    console.error("Invalid existing conditions JSON");
                }
            }

            var $rootGroup = renderGroup(initialData);
            // Don't allow deleting the root group
            $rootGroup.find('.btn-outline-danger').first().remove();
            
            $container.append($rootGroup);
            serializeBuilder();
            
            // Re-serialize on form submit just to be safe
            $container.closest('form').on('submit', function() {
                serializeBuilder();
            });
        }
    };
});
